use graham_ledger::{Ledger,OpeningInput,OpeningPosition,QuoteKey,QuoteInput,QuoteResponse};
fn key(market:&str,code:&str)->QuoteKey{QuoteKey{market:market.into(),code:code.into(),kind:"stock".into()}}
#[test]
fn holding_quotes_batch_by_market_update_valuation_and_never_rewrite_the_personal_ledger(){
 let dir=tempfile::tempdir().unwrap();let path=dir.path().join("ledger.sqlite3");let mut ledger=Ledger::open(&path).unwrap();let a=ledger.create_account("人民币","CNY").unwrap();let b=ledger.create_account("港币","HKD").unwrap();
 for(account,market,code,currency,qty,cost)in [(&a,"CN","600036","CNY","100","3000"),(&b,"HK","00700","HKD","10","4000")]{ledger.save_opening(&OpeningInput{account_id:account.clone(),occurred_on:"2026-10-23".into(),cash:"1000".into(),positions:vec![OpeningPosition{market:market.into(),code:code.into(),kind:"stock".into(),name:code.into(),currency:currency.into(),quantity:qty.into(),cost:cost.into(),reference_price:None}],note:"核对期初".into()},None).unwrap();}
 let before=ledger.snapshot().unwrap();let now=chrono::DateTime::parse_from_rfc3339("2026-10-26T14:20:00+08:00").unwrap().timestamp();let plan=ledger.begin_quote_refresh(now,false,false).unwrap();assert_eq!(plan.jobs.len(),2);assert!(plan.jobs.iter().all(|j|j.keys.len()==1));
 let cn=plan.jobs.iter().find(|j|j.feed=="cn-stock").unwrap();let hk=plan.jobs.iter().find(|j|j.feed=="hk").unwrap();
 ledger.finish_quote_job(cn,&QuoteResponse{feed:"cn-stock".into(),quotes:vec![QuoteInput{history:vec![],key:key("CN","600036"),currency:"CNY".into(),price:"35".into(),source_time:Some("14:19:59".into()),quoted_at:None}],error:None},now+1).unwrap();
 ledger.finish_quote_job(hk,&QuoteResponse{feed:"hk".into(),quotes:vec![QuoteInput{history:vec![],key:key("HK","00700"),currency:"HKD".into(),price:"450.5".into(),source_time:Some("2026/10/26 14:05:00".into()),quoted_at:Some("2026-10-26T14:05:00+08:00".into())}],error:None},now+2).unwrap();
 let state=ledger.quote_state(now+2,false).unwrap();let cn=state.holdings.iter().find(|h|h.account_id==a).unwrap();assert_eq!(cn.market_value.as_deref(),Some("3500.00"));assert_eq!(cn.unrealized.as_deref(),Some("500.00"));let hk=state.holdings.iter().find(|h|h.account_id==b).unwrap();assert_eq!(hk.market_value.as_deref(),Some("4505.00"));assert_eq!(hk.unrealized.as_deref(),Some("505.00"));
 let cn=state.quotes.iter().find(|q|q.key.market=="CN").unwrap();assert_eq!(cn.status,"time_unknown");assert!(cn.quoted_at.is_none());assert_eq!(cn.source_time.as_deref(),Some("14:19:59"));let hk=state.quotes.iter().find(|q|q.key.market=="HK").unwrap();assert_eq!(hk.delay_seconds,Some(900));assert_eq!(hk.quoted_at.as_deref(),Some("2026-10-26T14:05:00+08:00"));
 assert!(ledger.begin_quote_refresh(now+3,false,false).unwrap().jobs.is_empty());let after=ledger.snapshot().unwrap();assert_eq!(after.accounts,before.accounts);assert_eq!(after.positions,before.positions);assert_eq!(after.entries.len(),0);
 drop(ledger);let ledger=Ledger::open(&path).unwrap();assert_eq!(ledger.quote_state(now+10,false).unwrap().quotes.len(),2);assert_eq!(ledger.snapshot().unwrap().accounts,before.accounts);
}

#[test]
fn failures_back_off_and_older_or_invalid_responses_keep_the_last_effective_quote(){
 let dir=tempfile::tempdir().unwrap();let mut ledger=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let now=chrono::DateTime::parse_from_rfc3339("2026-10-26T14:20:00+08:00").unwrap().timestamp();let plan=ledger.begin_quote_refresh(now,true,false).unwrap();let hk=plan.jobs.iter().find(|j|j.feed=="hk").unwrap();let q=QuoteInput{history:vec![],key:key("HK","00700"),currency:"HKD".into(),price:"450.5".into(),source_time:Some("2026/10/26 14:05:00".into()),quoted_at:Some("2026-10-26T14:05:00+08:00".into())};let response=QuoteResponse{feed:"hk".into(),quotes:vec![q.clone()],error:None};ledger.finish_quote_job(hk,&response,now+1).unwrap();assert!(ledger.finish_quote_job(hk,&response,now+2).is_err());let original=ledger.quote_state(now+2,true).unwrap().quotes.into_iter().find(|q|q.key.market=="HK").unwrap();
 let plan=ledger.begin_quote_refresh(now+62,true,false).unwrap();let hk=plan.jobs.iter().find(|j|j.feed=="hk").unwrap();ledger.finish_quote_job(hk,&QuoteResponse{feed:"hk".into(),quotes:vec![],error:Some("连接失败".into())},now+63).unwrap();let state=ledger.quote_state(now+63,true).unwrap();let cached=state.quotes.iter().find(|q|q.key.market=="HK").unwrap();assert_eq!(cached.price,original.price);assert_eq!(cached.received_at,original.received_at);assert_eq!(cached.quoted_at,original.quoted_at);assert_eq!(cached.status,"stale");assert_eq!(chrono::DateTime::parse_from_rfc3339(cached.retry_at.as_ref().unwrap()).unwrap().timestamp(),now+123);assert!(ledger.begin_quote_refresh(now+64,true,false).unwrap().jobs.is_empty());
 let plan=ledger.begin_quote_refresh(now+124,true,false).unwrap();let hk=plan.jobs.iter().find(|j|j.feed=="hk").unwrap();let mut older=q.clone();older.price="1".into();older.source_time=Some("2026/10/26 14:04:00".into());older.quoted_at=Some("2026-10-26T14:04:00+08:00".into());ledger.finish_quote_job(hk,&QuoteResponse{feed:"hk".into(),quotes:vec![older],error:None},now+125).unwrap();let state=ledger.quote_state(now+125,true).unwrap();let cached=state.quotes.iter().find(|q|q.key.market=="HK").unwrap();assert_eq!(cached.price.as_deref(),Some("450.5"));assert_eq!(chrono::DateTime::parse_from_rfc3339(cached.retry_at.as_ref().unwrap()).unwrap().timestamp(),now+245);
 let plan=ledger.begin_quote_refresh(now+246,true,false).unwrap();let hk=plan.jobs.iter().find(|j|j.feed=="hk").unwrap();let mut wrong=q;wrong.currency="USD".into();ledger.finish_quote_job(hk,&QuoteResponse{feed:"hk".into(),quotes:vec![wrong],error:None},now+247).unwrap();let state=ledger.quote_state(now+247,true).unwrap();let hk=state.quotes.iter().find(|q|q.key.market=="HK").unwrap();assert_eq!(hk.price.as_deref(),Some("450.5"));assert!(hk.error.as_deref().unwrap().contains("币种"));assert!(state.holdings.is_empty());assert!(ledger.snapshot().unwrap().accounts.is_empty());
 let plan=ledger.begin_quote_refresh(now+488,true,false).unwrap();let hk=plan.jobs.iter().find(|j|j.feed=="hk").unwrap();ledger.finish_quote_job(hk,&QuoteResponse{feed:"hk".into(),quotes:vec![QuoteInput{history:vec![],key:key("HK","00700"),currency:"HKD".into(),price:"1".into(),source_time:None,quoted_at:None}],error:None},now+489).unwrap();let state=ledger.quote_state(now+489,true).unwrap();let hk=state.quotes.iter().find(|q|q.key.market=="HK").unwrap();assert_eq!(hk.price.as_deref(),Some("450.5"));assert_eq!(hk.status,"stale");assert_eq!(hk.quoted_at,original.quoted_at);
}
#[test]
fn quote_cache_failure_and_one_valuation_overflow_do_not_block_the_personal_ledger(){
 let dir=tempfile::tempdir().unwrap();let path=dir.path().join("ledger.sqlite3");std::fs::create_dir(path.with_extension("quotes.sqlite3")).unwrap();let mut ledger=Ledger::open(&path).unwrap();let a=ledger.create_account("可继续记账","CNY").unwrap();ledger.save_opening(&OpeningInput{account_id:a.clone(),occurred_on:"2026-10-23".into(),cash:"100".into(),positions:vec![OpeningPosition{market:"CN".into(),code:"600036".into(),kind:"stock".into(),name:"招商银行".into(),currency:"CNY".into(),quantity:"1000000000000".into(),cost:"0".into(),reference_price:None}],note:"边界核对".into()},None).unwrap();
 let now=chrono::DateTime::parse_from_rfc3339("2026-10-26T14:20:00+08:00").unwrap().timestamp();let p=ledger.begin_quote_refresh(now,false,false).unwrap();ledger.finish_quote_job(&p.jobs[0],&QuoteResponse{feed:"cn-stock".into(),quotes:vec![QuoteInput{history:vec![],key:key("CN","600036"),currency:"CNY".into(),price:"1000000000000".into(),source_time:None,quoted_at:None}],error:None},now+1).unwrap();let state=ledger.quote_state(now+1,false).unwrap();assert!(state.cache_warning.is_some());assert!(state.holdings[0].market_value.is_none());assert!(state.holdings[0].valuation_error.is_some());ledger.record_deposit(&a,"2026-10-26","1", "").unwrap();assert_eq!(ledger.snapshot().unwrap().accounts[0].balance,"101.00");
}

fn epoch(value:&str)->i64{chrono::DateTime::parse_from_rfc3339(value).unwrap().timestamp()}
#[test]
fn us_quote_and_daily_history_survive_offline_reopen_without_changing_holdings(){
 let dir=tempfile::tempdir().unwrap();let path=dir.path().join("ledger.sqlite3");let mut ledger=Ledger::open(&path).unwrap();let a=ledger.create_account("美股核对","USD").unwrap();ledger.save_opening(&OpeningInput{account_id:a.clone(),occurred_on:"2026-10-23".into(),cash:"1000".into(),positions:vec![OpeningPosition{market:"US".into(),code:"AAPL".into(),kind:"stock".into(),name:"苹果".into(),currency:"USD".into(),quantity:"10".into(),cost:"2000".into(),reference_price:None}],note:"".into()},None).unwrap();let before=ledger.snapshot().unwrap();let now=epoch("2026-10-26T14:00:00Z");let plan=ledger.begin_quote_refresh(now,false,true).unwrap();assert_eq!(plan.jobs.len(),1);assert_eq!(plan.jobs[0].feed,"us");
 let input:QuoteInput=serde_json::from_value(serde_json::json!({"key":{"market":"US","code":"AAPL","kind":"stock"},"price":"250.25","currency":"USD","sourceTime":"2026-10-26T09:59:00-04:00","quotedAt":"2026-10-26T09:59:00-04:00","history":[{"date":"2026-10-23","close":"249.5"},{"date":"2026-10-26","close":"250.25"}]})).unwrap();ledger.finish_quote_job(&plan.jobs[0],&QuoteResponse{feed:"us".into(),quotes:vec![input.clone()],error:None},now+1).unwrap();let state=ledger.quote_state(now+2,false).unwrap();assert_eq!(state.holdings[0].market_value.as_deref(),Some("2502.50"));assert_eq!(state.holdings[0].unrealized.as_deref(),Some("502.50"));assert_eq!(state.quotes[0].history[0].date,"2026-10-23");assert_eq!(state.quotes[0].history[0].close,"249.5");assert_eq!(state.quotes[0].quoted_at.as_deref(),Some("2026-10-26T09:59:00-04:00"));let received=state.quotes[0].received_at.clone();
 let plan=ledger.begin_quote_refresh(now+62,false,false).unwrap();let mut bad=input;bad.price="1".into();bad.history[0].close="0".into();ledger.finish_quote_job(&plan.jobs[0],&QuoteResponse{feed:"us".into(),quotes:vec![bad],error:None},now+63).unwrap();let state=ledger.quote_state(now+64,false).unwrap();assert_eq!(state.quotes[0].price.as_deref(),Some("250.25"));assert_eq!(state.quotes[0].status,"stale");assert_eq!(state.quotes[0].history[0].close,"249.5");assert_eq!(state.quotes[0].received_at,received);
 drop(ledger);let mut ledger=Ledger::open(&path).unwrap();let plan=ledger.begin_quote_refresh(now+124,false,false).unwrap();ledger.finish_quote_job(&plan.jobs[0],&QuoteResponse{feed:"us".into(),quotes:vec![],error:Some("网络断开".into())},now+125).unwrap();let state=ledger.quote_state(now+126,false).unwrap();assert_eq!(state.holdings[0].quantity,"10");assert_eq!(state.quotes[0].history.len(),2);assert_eq!(state.quotes[0].received_at,received);assert_eq!(ledger.snapshot().unwrap().positions,before.positions);assert_eq!(ledger.snapshot().unwrap().accounts,before.accounts);
}
#[test]
fn automatic_us_refresh_respects_new_york_daylight_saving_and_manual_closed_requests(){
 for (time,open)in [("2026-07-06T13:29:00Z",false),("2026-07-06T13:30:00Z",true),("2026-07-06T20:00:00Z",false),("2026-01-05T14:29:00Z",false),("2026-01-05T14:30:00Z",true),("2026-01-05T21:00:00Z",false),("2026-07-05T14:30:00Z",false)]{
  let dir=tempfile::tempdir().unwrap();let mut ledger=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let now=epoch(time);let state=ledger.quote_state(now,true).unwrap();assert_eq!(state.quotes.iter().find(|q|q.key.market=="US").unwrap().market_open,open,"{time}");let plan=ledger.begin_quote_refresh(now,true,true).unwrap();assert_eq!(plan.jobs.iter().any(|j|j.feed=="us"),open,"{time}");if !open{assert!(ledger.begin_quote_refresh(now,true,false).unwrap().jobs.iter().any(|j|j.feed=="us"));}
 }
}
#[test]
fn large_us_portfolios_rotate_bounded_batches_so_later_holdings_are_not_starved(){
 let dir=tempfile::tempdir().unwrap();let mut ledger=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let a=ledger.create_account("分批行情","USD").unwrap();let positions=(0..12).map(|i|OpeningPosition{market:"US".into(),code:format!("T{i:02}"),kind:"stock".into(),name:format!("样例{i}"),currency:"USD".into(),quantity:"1".into(),cost:"1".into(),reference_price:None}).collect();ledger.save_opening(&OpeningInput{account_id:a,occurred_on:"2026-10-23".into(),cash:"0".into(),positions,note:"".into()},None).unwrap();let now=epoch("2026-10-26T14:00:00Z");let first=ledger.begin_quote_refresh(now,false,true).unwrap();assert_eq!(first.jobs[0].keys.len(),10);ledger.finish_quote_job(&first.jobs[0],&QuoteResponse{feed:"us".into(),quotes:vec![],error:Some("暂时限频".into())},now+1).unwrap();assert!(ledger.begin_quote_refresh(now+30,false,true).unwrap().jobs.is_empty());let second=ledger.begin_quote_refresh(now+62,false,true).unwrap();assert_eq!(second.jobs[0].keys[0].code,"T10");assert_eq!(second.jobs[0].keys[1].code,"T11");assert!(ledger.snapshot().unwrap().positions.iter().all(|p|p.quantity=="1"));
}
